import os
import time
import threading
from datetime import datetime


class Flogger:
    def __init__(self, filename):
        ts_prefix = time.strftime("-%Y%d%m_%H%M%S", time.localtime())
        (root, ext) = os.path.splitext(filename)
        self._filename = root + ts_prefix + ext
        self._file = open(self._filename, "a+")
        self._last_flush = int(time.mktime(time.localtime()))
        self._access_mutex = threading.Lock()

    def destroy(self):
        self.flush_now()
        self._file.close()

    def write(self, msg, end="\n"):
        lt = datetime.utcnow()
        timestamp = "[" + lt.strftime("%d %H:%M:%S.%f")[:-3] + "] "
        msg_out = timestamp + msg
        self._access_mutex.acquire()
        self._file.write(msg_out + end)
        self._file.flush()
        self._access_mutex.release()
        return msg_out

    def flush_now(self):
        self._file.flush()
        os.fsync(self._file.fileno())

    def flush_if_necessary(self):
        fl = int(time.mktime(time.localtime()))
        if fl - self._last_flush >= 5:
            self.flush_now()
            self._last_flush = fl
